-- งาน: นำเข้าข้อมูลจากแหล่งอ้างอิง EPPO และบันทึก Source (SRC-01 ถึง SRC-18)
-- Query นี้เพิ่ม/ปรับปรุง metadata ในตาราง source เท่านั้น ไม่ได้นำเนื้อหา CSV ลง Exchange

ON CONFLICT (src_code) DO UPDATE SET
    dataset_name = EXCLUDED.dataset_name,
    agency = EXCLUDED.agency,
    data_owner = EXCLUDED.data_owner,
    url = EXCLUDED.url,
    accessed_date = EXCLUDED.accessed_date;
